def octagon_sec_agent(workspace_id, input, session_id=None, session_title=None, session_context=None, **_extra):
    import json, os, datetime, re, time, random, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0385000" if __import__("os").path.isdir("./environment_mix/0385000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "octagon-sec-agent"
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # ---- request log + rate limit (observable dynamics) ----
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []

    def _new_req_id():
        return f"oct_req_{int(time.time()*1000)}_{len(req_logs)+1}"

    def _log(status, workspace_id=None, api_key_id=None, meta=None):
        row = {
            "id": _new_req_id(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        if meta is not None:
            row["meta"] = meta
        req_logs.append(row)
        _save("request_logs.json", req_logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # simple per-workspace endpoint rate limit: 60/min
    def _enforce_rate_limit(ws_id):
        if not ws_id:
            return True, None
        cutoff = now - datetime.timedelta(seconds=60)
        n = 0
        for r in req_logs[-2000:]:
            if r.get("workspace_id") != ws_id or r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        if n >= 60:
            return False, _err("RATE_LIMIT", "Rate limit exceeded for this workspace on this endpoint (60/min).")
        return True, None

    # ---- validation ----
    if not isinstance(workspace_id, str) or not re.match(r"^oct_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "workspace_id must match ^oct_ws_[0-9A-HJKMNP-TV-Z]{10,}$.")
    if session_id is not None and (not isinstance(session_id, str) or not re.match(r"^oct_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id)):
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "session_id must match ^oct_sess_[0-9A-HJKMNP-TV-Z]{10,}$.")
    if session_title is not None and not isinstance(session_title, str):
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "session_title must be a string.")
    if session_context is not None and not isinstance(session_context, dict):
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "session_context must be an object.")
    if not isinstance(input, dict):
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "input must be an object.")

    ok, rl_err = _enforce_rate_limit(workspace_id)
    if not ok:
        _log("error", workspace_id=workspace_id, meta={"code": "RATE_LIMIT"})
        return rl_err

    # ---- load state ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    agent_tools = _load("agent_tools.json")
    sessions = _load("sessions.json")
    runs = _load("agent_runs.json")
    artifacts = _load("artifacts.json")

    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(agent_tools, list): agent_tools = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(runs, list): runs = []
    if not isinstance(artifacts, list): artifacts = []

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("error", workspace_id=workspace_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("error", workspace_id=workspace_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is not active; tool invocations are blocked by workspace status policy.")

    # tool row must exist
    tool = next((t for t in agent_tools if t.get("tool_name") == endpoint), None)
    if not tool:
        _log("error", workspace_id=workspace_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Unknown tool_name; no matching agent_tools row for this MCP tool.")
    if tool.get("status") != "enabled":
        _log("error", workspace_id=workspace_id, meta={"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "Tool is not enabled (disabled/deprecated).")

    # Ambient auth: pick an API key that can invoke this tool (or internal/system = None if none exists)
    def _key_can_invoke(k):
        if k.get("workspace_id") != workspace_id:
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp and not (now < exp):
            return False
        scopes = k.get("scopes")
        if not isinstance(scopes, list) or not scopes:
            return False
        return ("*" in scopes) or (endpoint in scopes)

    usable_keys = [k for k in api_keys if isinstance(k, dict) and _key_can_invoke(k)]
    api_key_id = usable_keys[0]["id"] if usable_keys else None

    # If there are API keys in this workspace but none can invoke, treat as unauthorized
    has_any_keys = any(k.get("workspace_id") == workspace_id for k in api_keys if isinstance(k, dict))
    if has_any_keys and api_key_id is None:
        _log("error", workspace_id=workspace_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active API key in this workspace is permitted to invoke this tool (status/expiry/scopes).")

    # ---- secret detection / redaction ----
    secret_key_names = {"api_key", "apikey", "authorization", "auth", "token", "secret", "password", "bearer"}
    value_patterns = [
        re.compile(r"\bsk-[A-Za-z0-9]{16,}\b"),
        re.compile(r"\bAKIA[0-9A-Z]{16}\b"),
        re.compile(r"\bAIza[0-9A-Za-z\-_]{20,}\b"),
        re.compile(r"\bghp_[A-Za-z0-9]{20,}\b"),
        re.compile(r"\bxox[baprs]-[0-9A-Za-z-]{10,}\b"),
        re.compile(r"\bBearer\s+[A-Za-z0-9\-\._~\+\/]+=*\b", re.IGNORECASE),
    ]

    def _redact(obj, key=None):
        detected = False
        if isinstance(key, str) and key.lower() in secret_key_names:
            if obj is not None:
                return "[REDACTED]", True
        if isinstance(obj, str):
            for p in value_patterns:
                if p.search(obj):
                    return "[REDACTED]", True
            return obj, False
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                rv, det = _redact(v, k)
                detected = detected or det
                out[k] = rv
            return out, detected
        if isinstance(obj, list):
            out_l = []
            for v in obj:
                rv, det = _redact(v, None)
                detected = detected or det
                out_l.append(rv)
            return out_l, detected
        return obj, False

    input_redacted, secret_detected = _redact(input)

    # ---- session resolve / create ----
    def _new_ulid(prefix):
        b32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        def enc(v, n):
            out = []
            for _ in range(n):
                out.append(b32[v % 32])
                v //= 32
            return "".join(reversed(out))
        rnd = random.getrandbits(80)
        return f"{prefix}{enc(ms, 10)}{enc(rnd, 16)}"

    sess = None
    if session_id:
        sess = next((s for s in sessions if s.get("id") == session_id), None)
        if not sess:
            _log("error", workspace_id=workspace_id, api_key_id=api_key_id, meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Session not found.")
        if sess.get("workspace_id") != workspace_id:
            _log("error", workspace_id=workspace_id, api_key_id=api_key_id, meta={"code": "CONFLICT"})
            return _err("CONFLICT", "session_id does not belong to workspace_id.")
    else:
        new_sid = _new_ulid("oct_sess_")
        sess = {
            "id": new_sid,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "title": session_title if isinstance(session_title, str) else None,
            "status": "open",
            "context": session_context if isinstance(session_context, dict) else None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sessions.append(sess)
        _save("sessions.json", sessions)

    if sess.get("status") != "open":
        _log("error", workspace_id=workspace_id, api_key_id=api_key_id, meta={"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "New agent runs are only allowed when sessions.status='open' (business rule).")

    # ---- quota: monthly runs ----
    def _month_bounds(dt):
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            end = start.replace(year=start.year + 1, month=1)
        else:
            end = start.replace(month=start.month + 1)
        return start, end

    start_m, end_m = _month_bounds(now)
    run_count = 0
    for r in runs:
        if r.get("workspace_id") != workspace_id:
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts and start_m <= ts < end_m:
            run_count += 1
    quota = ws.get("monthly_run_quota")
    if isinstance(quota, int) and quota >= 0 and run_count >= quota:
        _log("error", workspace_id=workspace_id, api_key_id=api_key_id, meta={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Monthly agent run quota exceeded for workspace (enforced at run creation time).", error_code="quota_exceeded")

    # ---- create run ----
    run_id = _new_ulid("oct_run_")
    run = {
        "id": run_id,
        "workspace_id": workspace_id,
        "session_id": sess["id"],
        "api_key_id": api_key_id,
        "tool_id": tool.get("id"),
        "input": input_redacted if isinstance(input_redacted, dict) else {},
        "status": "queued",
        "error_code": "secret_detected" if secret_detected else None,
        "error_message": "Input contained a suspected secret; content was redacted before storage." if secret_detected else None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "usage": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    runs.append(run)
    _save("agent_runs.json", runs)

    # update key last_used_at on successful auth usage
    if api_key_id is not None:
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

    # return run + existing artifacts (none are created by this offline tool)
    run_artifacts = [a for a in artifacts if a.get("run_id") == run_id and a.get("workspace_id") == workspace_id]
    _log("ok", workspace_id=workspace_id, api_key_id=api_key_id, meta={"created_run_id": run_id, "session_id": sess["id"]})
    return {
        "session": sess,
        "run": run,
        "artifacts": run_artifacts,
        "meta": {"tool_name": endpoint}
    }

