    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0)
    _now_iso = _now.isoformat() + "Z"

    # ---- helpers ----
    def _log_request(api_key_id, workspace_id, tool_name, status, error_code=None):
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "oct_req_" + hashlib.sha256(f"{tool_name}|{_now_iso}|{random.random()}".encode("utf-8")).hexdigest()[:26],
            "timestamp": _now_iso,
            "endpoint": tool_name,
            "tool_name": tool_name,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    def _ulid_like(prefix):
        # Not a real ULID, but stable and matches the given regex charset/length.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(26))

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Accept Z suffix
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _is_secretish(x):
        # Very lightweight secret detection. Redact obvious API-key-ish patterns.
        if isinstance(x, str):
            s = x
            if "sk-" in s or "api_key" in s.lower() or "apikey" in s.lower():
                return True
            # long high-entropy-ish tokens
            if len(s) >= 32 and re.fullmatch(r"[A-Za-z0-9_\-]{32,}", s or ""):
                return True
            return False
        if isinstance(x, dict):
            for k, v in x.items():
                if isinstance(k, str) and any(t in k.lower() for t in ["api_key", "apikey", "secret", "token", "bearer", "authorization"]):
                    return True
                if _is_secretish(v):
                    return True
            return False
        if isinstance(x, list):
            return any(_is_secretish(v) for v in x)
        return False

    def _redact_obj(x):
        if isinstance(x, str):
            if _is_secretish(x):
                return "[REDACTED]"
            return x
        if isinstance(x, dict):
            out = {}
            for k, v in x.items():
                if isinstance(k, str) and any(t in k.lower() for t in ["api_key", "apikey", "secret", "token", "bearer", "authorization"]):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact_obj(v)
            return out
        if isinstance(x, list):
            return [_redact_obj(v) for v in x]
        return x

    # ---- validate inputs ----
    ws_pat = re.compile(r"^oct_ws_[0-9A-HJKMNP-TV-Z]{10,}$")
    sess_pat = re.compile(r"^oct_sess_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(workspace_id, str) or not ws_pat.match(workspace_id):
        try: _log_request(None, workspace_id if isinstance(workspace_id, str) else None, "octagon-financials-agent", "error", "validation_error")
        except Exception: pass
        return _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")
    if session_id is not None and (not isinstance(session_id, str) or not sess_pat.match(session_id)):
        try: _log_request(None, workspace_id, "octagon-financials-agent", "error", "validation_error")
        except Exception: pass
        return _err("VALIDATION_ERROR", "session_id is malformed", field="session_id")
    if session_title is not None and not isinstance(session_title, str):
        try: _log_request(None, workspace_id, "octagon-financials-agent", "error", "validation_error")
        except Exception: pass
        return _err("VALIDATION_ERROR", "session_title must be a string", field="session_title")
    if session_title is not None and len(session_title) > 200:
        try: _log_request(None, workspace_id, "octagon-financials-agent", "error", "validation_error")
        except Exception: pass
        return _err("VALIDATION_ERROR", "session_title length must be <= 200", field="session_title")
    if session_context is not None and not isinstance(session_context, dict):
        try: _log_request(None, workspace_id, "octagon-financials-agent", "error", "validation_error")
        except Exception: pass
        return _err("VALIDATION_ERROR", "session_context must be an object", field="session_context")
    if not isinstance(input, dict):
        try: _log_request(None, workspace_id, "octagon-financials-agent", "error", "validation_error")
        except Exception: pass
        return _err("VALIDATION_ERROR", "input must be an object", field="input")

    # ---- load data ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    agent_tools = _load("agent_tools.json")
    sessions = _load("sessions.json")
    agent_runs = _load("agent_runs.json")
    artifacts = _load("artifacts.json")

    if not isinstance(workspaces, list) or not isinstance(api_keys, list) or not isinstance(agent_tools, list) or not isinstance(sessions, list) or not isinstance(agent_runs, list) or not isinstance(artifacts, list):
        try: _log_request(None, workspace_id, "octagon-financials-agent", "error", "storage_error")
        except Exception: pass
        return _err("CONFLICT", "Datastore is in an invalid state")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        try: _log_request(None, workspace_id, "octagon-financials-agent", "error", "not_found")
        except Exception: pass
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    # Workspace status enforcement
    if ws.get("status") != "active":
        # For tool invocation, reject if not active.
        try: _log_request(None, workspace_id, "octagon-financials-agent", "error", "workspace_inactive")
        except Exception: pass
        return _err("UNAUTHORIZED", "Workspace is not active", workspace_status=ws.get("status"))

    # ---- resolve tool row ----
    tool_name = "octagon-financials-agent"
    tool = next((t for t in agent_tools if isinstance(t, dict) and t.get("tool_name") == tool_name), None)
    if not tool:
        try: _log_request(None, workspace_id, tool_name, "error", "unknown_tool")
        except Exception: pass
        return _err("NOT_FOUND", "Tool is not registered", tool_name=tool_name)
    if tool.get("status") != "enabled":
        try: _log_request(None, workspace_id, tool_name, "error", "tool_disabled")
        except Exception: pass
        return _err("CONFLICT", "Tool is not enabled", tool_status=tool.get("status"))

    # ---- ambient authentication: pick any usable active API key in workspace with scope ----
    def _key_usable(k):
        if not isinstance(k, dict):
            return False
        if k.get("workspace_id") != workspace_id:
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and _now >= exp:
            return False
        scopes = k.get("scopes")
        if not isinstance(scopes, list) or len(scopes) == 0:
            return False
        if "*" in scopes or tool_name in scopes:
            return True
        return False

    usable_keys = [k for k in api_keys if _key_usable(k)]
    api_key = usable_keys[0] if usable_keys else None
    if api_key is None:
        try: _log_request(None, workspace_id, tool_name, "error", "unauthorized")
        except Exception: pass
        return _err("UNAUTHORIZED", "No active API key with required scope is available for this workspace", required_scope=tool_name)

    # Update last_used_at
    api_key_id = api_key.get("id")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = _now_iso
            k["updated_at"] = _now_iso
            break

    # ---- session resolution / creation ----
    sess = None
    if session_id is not None:
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
        if not sess:
            try: _log_request(api_key_id, workspace_id, tool_name, "error", "not_found")
            except Exception: pass
            return _err("NOT_FOUND", "Session not found", session_id=session_id)
        if sess.get("workspace_id") != workspace_id:
            try: _log_request(api_key_id, workspace_id, tool_name, "error", "validation_error")
            except Exception: pass
            return _err("VALIDATION_ERROR", "session_id does not belong to workspace_id")
        if sess.get("status") != "open":
            try: _log_request(api_key_id, workspace_id, tool_name, "error", "invalid_session_state")
            except Exception: pass
            return _err("INVALID_TRANSITION", "Cannot create a new run in a non-open session", session_status=sess.get("status"))
    else:
        # Create new session
        new_sess_id = _ulid_like("oct_sess_")
        sess = {
            "id": new_sess_id,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "title": session_title if session_title is not None else None,
            "status": "open",
            "context": session_context if session_context is not None else None,
            "created_at": _now_iso,
            "updated_at": _now_iso
        }
        sessions.append(sess)

    # ---- quota enforcement (monthly run quota) ----
    quota = ws.get("monthly_run_quota")
    if not isinstance(quota, int) or quota < 0:
        try: _log_request(api_key_id, workspace_id, tool_name, "error", "validation_error")
        except Exception: pass
        return _err("CONFLICT", "Workspace quota configuration invalid")
    current_month = _month_key(_now)
    month_runs = 0
    for r in agent_runs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            continue
        if _month_key(dt) == current_month:
            month_runs += 1
    if month_runs >= quota:
        # reject with quota_exceeded
        try: _log_request(api_key_id, workspace_id, tool_name, "error", "quota_exceeded")
        except Exception: pass
        return _err("QUOTA_EXCEEDED", "Monthly run quota exceeded", error_code="quota_exceeded", monthly_run_quota=quota)

    # ---- secret detection/redaction ----
    secret_detected = _is_secretish(input) or (session_context is not None and _is_secretish(session_context))
    safe_input = _redact_obj(input) if secret_detected else input

    # ---- create agent run ----
    run_id = _ulid_like("oct_run_")
    run = {
        "id": run_id,
        "workspace_id": workspace_id,
        "session_id": sess.get("id"),
        "api_key_id": api_key_id,
        "tool_id": tool.get("id"),
        "input": safe_input if isinstance(safe_input, dict) else {},
        "status": "queued",
        "error_code": "secret_detected" if secret_detected else None,
        "error_message": "Input was redacted due to possible secret material" if secret_detected else None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "usage": None,
        "created_at": _now_iso,
        "updated_at": _now_iso
    }
    agent_runs.append(run)

    # Persist mutations
    _save("api_keys.json", api_keys)
    _save("sessions.json", sessions)
    _save("agent_runs.json", agent_runs)

    # Return created run plus any stored analysis artifacts (currently none created by this endpoint itself)
    # Filter artifacts for this run (existing ones, if any)
    run_artifacts = [a for a in artifacts if isinstance(a, dict) and a.get("workspace_id") == workspace_id and a.get("run_id") == run_id]

    try: _log_request(api_key_id, workspace_id, tool_name, "ok", None)
    except Exception: pass

    return {
        "session": sess,
        "run": run,
        "artifacts": run_artifacts,
        "meta": {
            "tool_name": tool_name,
            "workspace_id": workspace_id
        }
    }

