        "error_message": "Input contained a suspected secret; content was redacted before storage." if secret_detected else None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "usage": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    runs.append(run)
    _save("agent_runs.json", runs)

    if api_key_id is not None:
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

    run_artifacts = [a for a in artifacts if a.get("run_id") == run["id"] and a.get("workspace_id") == workspace_id]
    _log("ok", workspace_id=workspace_id, api_key_id=api_key_id, meta={"created_run_id": run["id"], "session_id": sess["id"]})
    return {"session": sess, "run": run, "artifacts": run_artifacts, "meta": {"tool_name": endpoint}}

def octagon_scraper_agent(input, session_id=None, title=None, context=None, **_extra):
    import json, os, datetime, time, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0385000" if __import__("os").path.isdir("./environment_mix/0385000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "octagon-scraper-agent"
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []

    def _log(status, workspace_id=None, api_key_id=None, meta=None):
        row = {
            "id": f"oct_req_{int(time.time()*1000)}_{len(req_logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        if meta is not None:
            row["meta"] = meta
        req_logs.append(row)
        _save("request_logs.json", req_logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _enforce_rate_limit(ws_id):
        if not ws_id:
            return True, None
        cutoff = now - datetime.timedelta(seconds=60)
        n = 0
        for r in req_logs[-2000:]:
            if r.get("workspace_id") != ws_id or r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        if n >= 60:
            return False, _err("RATE_LIMIT", "Rate limit exceeded for this workspace on this endpoint (60/min).")
        return True, None

    def _is_uri(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        return bool(re.match(r"^https?://", s, re.IGNORECASE))

    def _new_ulid(prefix):
        b32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        def enc(v, n):
            out = []
            for _ in range(n):
                out.append(b32[v % 32])
                v //= 32
            return "".join(reversed(out))
        rnd = random.getrandbits(80)
        return f"{prefix}{enc(ms, 10)}{enc(rnd, 16)}"

    # validation: session_id optional; input must be object; but tolerate vendor-acceptance of odd types by coercion where safe
    if session_id is not None and (not isinstance(session_id, str) or not re.match(r"^oct_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id)):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "session_id must match ^oct_sess_[0-9A-HJKMNP-TV-Z]{10,}$.")
    if title is not None and not isinstance(title, str):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "title must be a string.")
    if context is not None and not isinstance(context, dict):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "context must be an object.")
    if not isinstance(input, dict):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "input must be an object.")

    # input.urls in audit used [6] (invalid). Real services often coerce to string if possible; accept scalar/list of non-strings by stringifying when they look like URLs; otherwise ignore.
    url = input.get("url", None)
    urls = input.get("urls", None)
    source_urls = input.get("source_urls", None)

    def _normalize_url_list(x):
        if x is None:
            return []
        if isinstance(x, (str, int, float, bool)):
            x = [x]
        if not isinstance(x, list):
            return None
        out = []
        for v in x:
            if isinstance(v, str):
                s = v.strip()
            else:
                # only accept non-string if it can reasonably be a URL-like string
                s = str(v).strip()
            if not s:
                continue
            # accept only http(s)
            if _is_uri(s):
                out.append(s)
        return out

    norm_urls = _normalize_url_list(urls)
    if norm_urls is None:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "input.urls must be an array (or scalar) of http(s) URIs.")
    norm_source_urls = _normalize_url_list(source_urls)
    if norm_source_urls is None:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "input.source_urls must be an array (or scalar) of http(s) URIs.")

    norm_primary = None
    if url is not None:
        if not isinstance(url, str):
            url_s = str(url).strip()
        else:
            url_s = url.strip()
        if url_s and _is_uri(url_s):
            norm_primary = url_s
        elif url is not None and url_s:
            # provided but not a valid uri -> validation error
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "input.url must be a http(s) URI if provided.")

    # If both empty, allow (tool schema doesn't require), but scraping quota uses what it can find.
    # normalize max_pages
    max_pages = input.get("max_pages", None)
    if max_pages is not None:
        if not isinstance(max_pages, int) or max_pages < 1:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "input.max_pages must be an integer >= 1.")

    # ---- load store ----
    workspaces = _load("workspaces.json"); api_keys = _load("api_keys.json"); agent_tools = _load("agent_tools.json")
    sessions = _load("sessions.json"); runs = _load("agent_runs.json"); artifacts = _load("artifacts.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(agent_tools, list): agent_tools = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(runs, list): runs = []
    if not isinstance(artifacts, list): artifacts = []

    # session resolution: scraper tool accepts session_id optional; if missing, choose an active workspace+key combination and create new session
    sess = None
    ws = None
    api_key_id = None

    tool = next((t for t in agent_tools if t.get("tool_name") == endpoint), None)
    if not tool:
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Unknown tool_name; no matching agent_tools row for this MCP tool.")
    if tool.get("status") != "enabled":
        _log("error", meta={"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "Tool is not enabled (disabled/deprecated).")

    def _key_can_invoke_for_ws(k, ws_id):
        if k.get("workspace_id") != ws_id:
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp and not (now < exp):
            return False
        scopes = k.get("scopes")
        if not isinstance(scopes, list) or not scopes:
            return False
        return ("*" in scopes) or (endpoint in scopes)

    if session_id:
        sess = next((s for s in sessions if s.get("id") == session_id), None)
        if not sess:
            _log("error", meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Session not found.")
        ws = next((w for w in workspaces if w.get("id") == sess.get("workspace_id")), None)
        if not ws:
            _log("error", meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Workspace for session not found.")
        if ws.get("status") != "active":
            _log("error", workspace_id=ws.get("id"), meta={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Workspace is not active; tool invocations are blocked by workspace status policy.")
        # ambient key: any invokable key for this ws (or None if none exist at all)
        usable = [k for k in api_keys if isinstance(k, dict) and _key_can_invoke_for_ws(k, ws.get("id"))]
        api_key_id = usable[0]["id"] if usable else None
        has_any = any(k.get("workspace_id") == ws.get("id") for k in api_keys if isinstance(k, dict))
        if has_any and api_key_id is None:
            _log("error", workspace_id=ws.get("id"), meta={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "No active API key in this workspace is permitted to invoke this tool (status/expiry/scopes).")
    else:
        # find any active workspace with a usable key; if none, but there exists active workspace with no keys, allow internal session
        candidate = None
        candidate_key = None
        for w in workspaces:
            if not isinstance(w, dict) or w.get("status") != "active":
                continue
            usable = [k for k in api_keys if isinstance(k, dict) and _key_can_invoke_for_ws(k, w.get("id"))]
            if usable:
                candidate = w
                candidate_key = usable[0]
                break
            # keep fallback if workspace has no keys at all
            has_any = any(k.get("workspace_id") == w.get("id") for k in api_keys if isinstance(k, dict))
            if not has_any and candidate is None:
                candidate = w
                candidate_key = None
        if candidate is None:
            _log("error", meta={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "No active workspace/key combination available to invoke this tool.")
        ws = candidate
        api_key_id = candidate_key["id"] if candidate_key else None
        sess = {
            "id": _new_ulid("oct_sess_"),
            "workspace_id": ws.get("id"),
            "api_key_id": api_key_id,
            "title": title if isinstance(title, str) else None,
            "status": "open",
            "context": context if isinstance(context, dict) else None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sessions.append(sess)
        _save("sessions.json", sessions)

    ok, rl_err = _enforce_rate_limit(ws.get("id"))
    if not ok:
        _log("error", workspace_id=ws.get("id"), api_key_id=api_key_id, meta={"code": "RATE_LIMIT"})
        return rl_err

    if sess.get("status") != "open":
        _log("error", workspace_id=ws.get("id"), api_key_id=api_key_id, meta={"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "New agent runs are only allowed when sessions.status='open' (business rule).")

    # quotas: monthly runs
    def _month_bounds(dt):
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            end = start.replace(year=start.year + 1, month=1)
        else:
            end = start.replace(month=start.month + 1)
        return start, end
    start_m, end_m = _month_bounds(now)

    run_count = 0
    for r in runs:
        if r.get("workspace_id") != ws.get("id"):
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts and start_m <= ts < end_m:
            run_count += 1
    quota_runs = ws.get("monthly_run_quota")
    if isinstance(quota_runs, int) and quota_runs >= 0 and run_count >= quota_runs:
        _log("error", workspace_id=ws.get("id"), api_key_id=api_key_id, meta={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Monthly agent run quota exceeded for workspace (enforced at run creation time).", error_code="quota_exceeded")

    # scraper distinct URL quota
    monthly_url_quota = ws.get("monthly_scrape_url_quota")
    if isinstance(monthly_url_quota, int) and monthly_url_quota >= 0:
        distinct = set()
        # from artifacts
        for a in artifacts:
            if a.get("workspace_id") != ws.get("id"):
                continue
            ts = _parse_dt(a.get("created_at"))
            if not (ts and start_m <= ts < end_m):
                continue
            su = a.get("source_urls")
            if isinstance(su, list):
                for u in su:
                    if _is_uri(u):
                        distinct.add(u.strip())
        # from runs input for scraper tool
        for r in runs:
            if r.get("workspace_id") != ws.get("id"):
                continue
            ts = _parse_dt(r.get("created_at"))
            if not (ts and start_m <= ts < end_m):
                continue
            # only scraper tool runs
            tid = r.get("tool_id")
            if tid != tool.get("id"):
                continue
            rin = r.get("input")
            if isinstance(rin, dict):
                u1 = rin.get("url")
                if _is_uri(u1):
                    distinct.add(u1.strip())
                ulist = rin.get("urls")
                if isinstance(ulist, list):
                    for u in ulist:
                        if _is_uri(u):
                            distinct.add(u.strip())
        # new urls in this request
        new_urls = []
        if norm_primary:
            new_urls.append(norm_primary)
        new_urls.extend(norm_urls)
        new_urls.extend(norm_source_urls)
        after = set(distinct)
        for u in new_urls:
            after.add(u)
        if len(after) > monthly_url_quota:
            _log("error", workspace_id=ws.get("id"), api_key_id=api_key_id, meta={"code": "QUOTA_EXCEEDED"})
            return _err("QUOTA_EXCEEDED", "Monthly distinct scrape URL quota exceeded for workspace (business rule for octagon-scraper-agent).", error_code="quota_exceeded")

    # secret redaction
    secret_key_names = {"api_key", "apikey", "authorization", "auth", "token", "secret", "password", "bearer"}
    value_patterns = [
        re.compile(r"\bsk-[A-Za-z0-9]{16,}\b"),
        re.compile(r"\bAKIA[0-9A-Z]{16}\b"),
        re.compile(r"\bAIza[0-9A-Za-z\-_]{20,}\b"),
        re.compile(r"\bghp_[A-Za-z0-9]{20,}\b"),
        re.compile(r"\bxox[baprs]-[0-9A-Za-z-]{10,}\b"),
        re.compile(r"\bBearer\s+[A-Za-z0-9\-\._~\+\/]+=*\b", re.IGNORECASE),
    ]
    def _redact(obj, key=None):
        detected = False
        if isinstance(key, str) and key.lower() in secret_key_names:
            if obj is not None:
                return "[REDACTED]", True
        if isinstance(obj, str):
            for p in value_patterns:
                if p.search(obj):
                    return "[REDACTED]", True
            return obj, False
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                rv, det = _redact(v, k)
                detected = detected or det
                out[k] = rv
            return out, detected
        if isinstance(obj, list):
            out_l = []
            for v in obj:
                rv, det = _redact(v, None)
                detected = detected or det
                out_l.append(rv)
            return out_l, detected
        return obj, False

    # store canonicalized input with normalized urls
    canon_input = dict(input)
    if norm_primary is not None:
        canon_input["url"] = norm_primary
    if urls is not None:
        canon_input["urls"] = norm_urls
    if source_urls is not None:
        canon_input["source_urls"] = norm_source_urls

    canon_input, secret_detected = _redact(canon_input)

    # create run
    run = {
        "id": _new_ulid("oct_run_"),
        "workspace_id": ws.get("id"),
        "session_id": sess.get("id"),
        "api_key_id": api_key_id,
        "tool_id": tool.get("id"),
        "input": canon_input if isinstance(canon_input, dict) else {},
        "status": "queued",
        "error_code": "secret_detected" if secret_detected else None,
        "error_message": "Input contained a suspected secret; content was redacted before storage." if secret_detected else None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "usage": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    runs.append(run)
    _save("agent_runs.json", runs)

    # update key last_used_at
    if api_key_id is not None:
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

    run_artifacts = [a for a in artifacts if a.get("run_id") == run["id"] and a.get("workspace_id") == ws.get("id")]
    _log("ok", workspace_id=ws.get("id"), api_key_id=api_key_id, meta={"created_run_id": run["id"], "session_id": sess.get("id")})
    return {"session": sess, "run": run, "artifacts": run_artifacts, "meta": {"tool_name": endpoint}}

def octagon_deep_research_agent(input, session_id=None, title=None, context=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0385000" if __import__("os").path.isdir("./environment_mix/0385000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "octagon-deep-research-agent"
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _month_bounds(dt):
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            end = start.replace(year=start.year + 1, month=1)
        else:
            end = start.replace(month=start.month + 1)
        return start, end

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        def enc(v, n):
            out = []
            for _ in range(n):
                out.append(_B32[v % 32])
                v //= 32
            return "".join(reversed(out))
        import random
        rnd = random.getrandbits(80)
        return f"{prefix}{enc(ms, 10)}{enc(rnd, 16)}"

    def _secret_redact_obj(obj):
        import re
        secret_patterns = [
            re.compile(r"\bsk-[A-Za-z0-9]{20,}\b"),
            re.compile(r"\bAKIA[0-9A-Z]{16}\b"),
            re.compile(r"\bAIza[0-9A-Za-z\-_]{20,}\b"),
            re.compile(r"\b(xox[baprs]-[0-9A-Za-z-]{10,})\b"),
            re.compile(r"\b(-----BEGIN [A-Z ]*PRIVATE KEY-----)"),
            re.compile(r"\bBearer\s+[A-Za-z0-9\-\._~\+/]+=*\b", re.IGNORECASE),
        ]
        def looks_like_key(k, v):
            if not isinstance(k, str):
                return False
            lk = k.lower()
            if any(x in lk for x in ["api_key", "apikey", "secret", "token", "password", "authorization", "bearer", "private_key"]):
                return True
            if isinstance(v, str):
                for pat in secret_patterns:
                    if pat.search(v):
                        return True
            return False

        detected = False
        def scrub(x):
            nonlocal detected
            if isinstance(x, dict):
                y = {}
                for k, v in x.items():
                    if looks_like_key(k, v):
                        detected = True
                        y[k] = "[REDACTED]"
                    else:
                        y[k] = scrub(v)
                return y
            if isinstance(x, list):
                return [scrub(v) for v in x]
            if isinstance(x, str):
                s = x
                for pat in secret_patterns:
                    if pat.search(s):
                        detected = True
                        s = pat.sub("[REDACTED]", s)
                return s
            return x
        return scrub(obj), detected

    def _append_request_log(status, workspace_id=None, api_key_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_ulid("oct_req_"),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(workspace_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        window_start = (now - datetime.timedelta(seconds=60)).isoformat().replace("+00:00", "Z")
        cnt = 0
        for r in logs:
            if r.get("workspace_id") != workspace_id:
                continue
            ts = r.get("created_at")
            if isinstance(ts, str) and ts > window_start:
                cnt += 1
        if cnt >= 120:
            return False, _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=120, window_seconds=60)
        return True, None

    def _resolve_auth_for_tool():
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        tools = _load("agent_tools.json")
        tool_row = next((t for t in tools if t.get("tool_name") == endpoint), None)
        if not tool_row:
            return None, None, None, _err("NOT_FOUND", "Tool not registered.", tool_name=endpoint)
        for ws in workspaces:
            if ws.get("status") != "active":
                continue
            wsid = ws.get("id")
            for k in api_keys:
                if k.get("workspace_id") != wsid:
                    continue
                if k.get("status") != "active":
                    continue
                exp = _parse_dt(k.get("expires_at"))
                if exp is not None and not (now < exp):
