        ]
        def looks_like_key(k, v):
            if not isinstance(k, str):
                return False
            lk = k.lower()
            if any(x in lk for x in ["api_key", "apikey", "secret", "token", "password", "authorization", "bearer", "private_key"]):
                return True
            if isinstance(v, str):
                for pat in secret_patterns:
                    if pat.search(v):
