        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        window_start = (now - datetime.timedelta(seconds=60)).isoformat().replace("+00:00", "Z")
        cnt = 0
        for r in logs:
            if r.get("workspace_id") != wsid:
                continue
            ts = r.get("created_at")
            if isinstance(ts, str) and ts > window_start:
                cnt += 1
        if cnt >= 240:  # reads slightly higher
            return False, _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=240, window_seconds=60)
        return True, None

    def _resolve_auth_for_workspace(wsid):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws = next((w for w in workspaces if w.get("id") == wsid), None)
        if not ws:
            return None, None, _err("NOT_FOUND", "Workspace not found.", workspace_id=wsid)
        if ws.get("status") == "deleted":
            return ws, None, _err("NOT_FOUND", "Workspace not found.", workspace_id=wsid)
        # Ambient: choose any active key in this workspace for visibility rules
        for k in api_keys:
            if k.get("workspace_id") != wsid:
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and not (now < exp):
                continue
            return ws, k, None
        return ws, None, _err("UNAUTHORIZED", "No valid API key for this workspace.")

    # validate
    if not isinstance(workspace_id, str) or not re.match(r"^oct_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        _append_request_log("error", None, None, "validation_error")
        return _err("VALIDATION_ERROR", "Invalid 'workspace_id' format.")
    if status is not None and status not in ["open","archived","deleted"]:
        _append_request_log("error", workspace_id, None, "validation_error")
        return _err("VALIDATION_ERROR", "Invalid 'status' filter.")
    if q is not None and not isinstance(q, str):
        _append_request_log("error", workspace_id, None, "validation_error")
        return _err("VALIDATION_ERROR", "Parameter 'q' must be a string.")
    ca = _parse_dt(created_after) if created_after is not None else None
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_after is not None and ca is None:
        _append_request_log("error", workspace_id, None, "validation_error")
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 date-time.")
    if created_before is not None and cb is None:
        _append_request_log("error", workspace_id, None, "validation_error")
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 date-time.")
    if ca is not None and cb is not None and cb <= ca:
        _append_request_log("error", workspace_id, None, "validation_error")
        return _err("VALIDATION_ERROR", "created_before must be strictly after created_after.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _append_request_log("error", workspace_id, None, "validation_error")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if sort is None:
        sort = "updated_at_desc"
    if sort not in ["created_at_desc","created_at_asc","updated_at_desc","updated_at_asc"]:
        _append_request_log("error", workspace_id, None, "validation_error")
        return _err("VALIDATION_ERROR", "Invalid 'sort' value.")
    if cursor is not None and not isinstance(cursor, str):
        _append_request_log("error", workspace_id, None, "validation_error")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    ws, key, auth_err = _resolve_auth_for_workspace(workspace_id)
    if auth_err:
        _append_request_log("error", workspace_id, None if key is None else key.get("id"), auth_err["error"]["code"].lower())
        return auth_err

    ok_rl, rl_err = _rate_limit_check(workspace_id)
    if not ok_rl:
        _append_request_log("error", workspace_id, key.get("id") if key else None, "rate_limit")
        return rl_err

    # fetch sessions
    sessions = _load("sessions.json")
    rows = [s for s in sessions if s.get("workspace_id") == workspace_id]

    # apply filters
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]
    if q is not None and q.strip():
        qq = q.strip().lower()
        def _match(s):
            t = s.get("title")
            if isinstance(t, str) and qq in t.lower():
                return True
            ctx = s.get("context")
            if isinstance(ctx, dict):
                # loose match on some top-level string values
                for v in ctx.values():
                    if isinstance(v, str) and qq in v.lower():
                        return True
            return False
        rows = [s for s in rows if _match(s)]
    if ca is not None:
        ca_iso = ca.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        rows = [s for s in rows if isinstance(s.get("created_at"), str) and s["created_at"] > ca_iso]
    if cb is not None:
        cb_iso = cb.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        rows = [s for s in rows if isinstance(s.get("created_at"), str) and s["created_at"] < cb_iso]

    # sort
    key_field, direction = sort.split("_")[:2], sort.split("_")[-1]
    if sort.startswith("created_at"):
        sf = "created_at"
    else:
        sf = "updated_at"
    reverse = sort.endswith("_desc")
    rows.sort(key=lambda r: (r.get(sf) is None, r.get(sf) or "", r.get("id") or ""), reverse=reverse)

    # cursor: opaque base64 json with last_value and last_id
    start_idx = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cur = json.loads(raw.decode("utf-8"))
            last_v = cur.get("v")
            last_id = cur.get("id")
            # find first row after cursor according to sort
            def _cmp_tuple(r):
                return (r.get(sf) or "", r.get("id") or "")
            if last_v is not None and last_id is not None:
                last_t = (last_v, last_id)
                for i, r in enumerate(rows):
                    t = _cmp_tuple(r)
                    if reverse:
                        if t < last_t:
                            start_idx = i
                            break
                    else:
                        if t > last_t:
                            start_idx = i
                            break
                else:
                    start_idx = len(rows)
        except Exception:
            _append_request_log("error", workspace_id, key.get("id") if key else None, "validation_error")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = rows[start_idx:start_idx + limit]
    total = len(rows)
    has_more = (start_idx + limit) < total
    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"v": last.get(sf) or "", "id": last.get("id") or ""}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # update api key last_used_at (read still counts as usage)
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if key and k.get("id") == key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    _append_request_log("ok", workspace_id, key.get("id") if key else None, None)
    return {
        "sessions": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort
        }
    }

def octagon_get_session(workspace_id, session_id, include_context=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0385000" if __import__("os").path.isdir("./environment_mix/0385000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "octagon-get-session"
    request_logs = _load("request_logs.json")

    def _log(status, workspace_id=None, api_key_id=None, meta=None):
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"oct_req_{int(time.time()*1000)}_{len(request_logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        if meta is not None:
            row["meta"] = meta
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _is_secret(val):
        if not isinstance(val, str):
            return False
        s = val.lower()
        if "oct_sk_" in s or "api_key" in s or "bearer " in s:
            return True
        if re.search(r"\bsk-[a-z0-9]{20,}\b", s):
            return True
        return False

    def _redact_obj(o):
        if isinstance(o, dict):
            out = {}
            for k, v in o.items():
                if isinstance(k, str) and re.search(r"(api[_-]?key|token|secret|password|authorization)", k, re.I):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact_obj(v)
            return out
        if isinstance(o, list):
            return [_redact_obj(x) for x in o]
        if isinstance(o, str):
            return "[REDACTED]" if _is_secret(o) else o
        return o

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^oct_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        _log("error", workspace_id=None, api_key_id=None, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(session_id, str) or not re.match(r"^oct_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id):
        _log("error", workspace_id=workspace_id, api_key_id=None, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid session_id.")
    if include_context is None:
        include_context = True
    if not isinstance(include_context, bool):
        _log("error", workspace_id=workspace_id, api_key_id=None, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_context must be boolean.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("error", workspace_id=workspace_id, api_key_id=None, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") == "deleted":
        _log("error", workspace_id=workspace_id, api_key_id=None, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("error", workspace_id=workspace_id, api_key_id=None, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is not active.")

    sessions = _load("sessions.json")
    sess = next((s for s in sessions if s.get("id") == session_id and s.get("workspace_id") == workspace_id), None)
    if not sess:
        _log("error", workspace_id=workspace_id, api_key_id=None, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Session not found.")

    # Ambient auth: require that there exists at least one active, unexpired key in workspace that could read sessions.
    api_keys = _load("api_keys.json")
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    def _key_ok(k):
        if k.get("workspace_id") != workspace_id:
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and not (now_dt < exp):
            return False
        scopes = k.get("scopes")
        if not isinstance(scopes, list) or not scopes:
            return False
        # Treat any presence as sufficient for read endpoints; enforce tool scopes only on tool invocations.
        return True

    key = next((k for k in api_keys if _key_ok(k)), None)
    if not key:
        _log("error", workspace_id=workspace_id, api_key_id=None, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No valid API key available for this workspace.")

    # Update last_used_at for the chosen key
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for k in api_keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    out = dict(sess)
    if not include_context:
        out.pop("context", None)
    else:
        # Redact secrets if any
        if "context" in out:
            out["context"] = _redact_obj(out.get("context"))

    _log("ok", workspace_id=workspace_id, api_key_id=key.get("id"))
    return {"session": out}

def octagon_update_session(workspace_id, session_id, title=None, context=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0385000" if __import__("os").path.isdir("./environment_mix/0385000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "octagon-update-session"
    request_logs = _load("request_logs.json")
    def _log(status_s, workspace_id=None, api_key_id=None, meta=None):
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"oct_req_{int(time.time()*1000)}_{len(request_logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        if meta is not None:
            row["meta"] = meta
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                return dt
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _contains_secret(o):
        if isinstance(o, dict):
            for k, v in o.items():
                if isinstance(k, str) and re.search(r"(api[_-]?key|token|secret|password|authorization)", k, re.I):
                    return True
                if _contains_secret(v):
                    return True
            return False
        if isinstance(o, list):
            return any(_contains_secret(x) for x in o)
        if isinstance(o, str):
            s = o.lower()
            if "oct_sk_" in s or "bearer " in s:
                return True
            if re.search(r"\bsk-[a-z0-9]{20,}\b", s):
                return True
        return False

    def _redact_obj(o):
        if isinstance(o, dict):
            out = {}
            for k, v in o.items():
                if isinstance(k, str) and re.search(r"(api[_-]?key|token|secret|password|authorization)", k, re.I):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact_obj(v)
            return out
        if isinstance(o, list):
            return [_redact_obj(x) for x in o]
        if isinstance(o, str):
            s = o.lower()
            if "oct_sk_" in s or "bearer " in s or re.search(r"\bsk-[a-z0-9]{20,}\b", s):
                return "[REDACTED]"
            return o
        return o

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^oct_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(session_id, str) or not re.match(r"^oct_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id):
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid session_id.")
    if title is not None:
        if not isinstance(title, str):
            _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "title must be a string.")
        if len(title) > 200:
            _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "title must be <= 200 characters.")
    if context is not None and not isinstance(context, dict):
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "context must be an object.")
    if status is not None:
        if status not in ["open", "archived", "deleted"]:
            _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid status.")
    if title is None and context is None and status is None:
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "No updates provided.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("error", workspace_id=workspace_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") == "deleted":
        _log("error", workspace_id=workspace_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("error", workspace_id=workspace_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # Ambient auth: choose an active, unexpired key for workspace
    api_keys = _load("api_keys.json")
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    def _key_ok(k):
        if k.get("workspace_id") != workspace_id:
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and not (now_dt < exp):
            return False
        scopes = k.get("scopes")
        return isinstance(scopes, list) and len(scopes) > 0

    key = next((k for k in api_keys if _key_ok(k)), None)
    if not key:
        _log("error", workspace_id=workspace_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No valid API key available for this workspace.")

    sessions = _load("sessions.json")
    idx = next((i for i, s in enumerate(sessions) if s.get("id") == session_id and s.get("workspace_id") == workspace_id), None)
    if idx is None:
        _log("error", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Session not found.")

    sess = sessions[idx]
    if sess.get("status") == "deleted":
        _log("error", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "Cannot update a deleted session.")

    # Validate lifecycle transition
    transitions = {"open": ["archived", "deleted"], "archived": ["open", "deleted"], "deleted": []}
    if status is not None and status != sess.get("status"):
        cur = sess.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _log("error", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"code": "INVALID_TRANSITION", "from": cur, "to": status})
            return _err("INVALID_TRANSITION", f"Invalid session status transition from '{cur}' to '{status}'.", from_status=cur, to_status=status)

    # Apply updates
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    changed = False
    if title is not None:
        sess["title"] = title
        changed = True
    if context is not None:
        if _contains_secret(context):
            sess["context"] = _redact_obj(context)
        else:
            sess["context"] = context
        changed = True
    if status is not None and status != sess.get("status"):
        sess["status"] = status
        changed = True
        # If deleting, redact context for tombstone-like behavior
        if status == "deleted":
            if sess.get("context") is not None:
                sess["context"] = {"tombstone": True}
    if not changed:
        _log("error", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"code": "CONFLICT"})
        return _err("CONFLICT", "No changes applied.")

    sess["updated_at"] = now_iso
    sessions[idx] = sess
    _save("sessions.json", sessions)

    # Update last_used_at for the chosen key
    for k in api_keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    _log("ok", workspace_id=workspace_id, api_key_id=key.get("id"))
    return {"session": sess}

