            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        if meta is not None:
            row["meta"] = meta
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _is_secret_str(val):
        if not isinstance(val, str):
            return False
        s = val.lower()
        if "oct_sk_" in s or "bearer " in s:
            return True
        if re.search(r"\bsk-[a-z0-9]{20,}\b", s):
            return True
        return False

    def _redact_obj(o):
        if isinstance(o, dict):
            out = {}
            for k, v in o.items():
                if isinstance(k, str) and re.search(r"(api[_-]?key|token|secret|password|authorization)", k, re.I):
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact_obj(v)
            return out
        if isinstance(o, list):
            return [_redact_obj(x) for x in o]
        if isinstance(o, str):
            return "[REDACTED]" if _is_secret_str(o) else o
        return o

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^oct_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if session_id is not None and (not isinstance(session_id, str) or not re.match(r"^oct_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id)):
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid session_id.")
    if status is not None and status not in ["queued", "running", "succeeded", "failed", "cancelled"]:
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid status.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if sort is None:
        sort = "created_at_desc"
    if sort not in ["created_at_desc", "created_at_asc"]:
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if include_input is None:
        include_input = False
    if not isinstance(include_input, bool):
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_input must be boolean.")

    ca = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 date-time.")
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 date-time.")
    if ca and cb and not (ca < cb):
        _log("error", workspace_id=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_after must be strictly before created_before.")

    # Workspace checks
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("error", workspace_id=workspace_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") == "deleted":
        _log("error", workspace_id=workspace_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")

    # Ambient auth: require at least one active, unexpired key for workspace
    api_keys = _load("api_keys.json")
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    def _key_ok(k):
        if k.get("workspace_id") != workspace_id:
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and not (now_dt < exp):
            return False
        scopes = k.get("scopes")
        return isinstance(scopes, list) and len(scopes) > 0

    key = next((k for k in api_keys if _key_ok(k)), None)
    if not key:
        _log("error", workspace_id=workspace_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key.")

    # Validate tool_name reference if provided
    tool_id = None
    if tool_name is not None:
        if not isinstance(tool_name, str) or not tool_name:
            _log("error", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "tool_name must be a string.")
        agent_tools = _load("agent_tools.json")
        tool = next((t for t in agent_tools if t.get("tool_name") == tool_name), None)
        if not tool:
            _log("error", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Unknown tool_name.")
        tool_id = tool.get("id")

    # Cursor decode
    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("error", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==")
            cursor_obj = json.loads(raw.decode("utf-8"))
        except Exception:
            _log("error", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        if not isinstance(cursor_obj, dict) or "created_at" not in cursor_obj or "id" not in cursor_obj:
            _log("error", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        if _parse_dt(cursor_obj.get("created_at")) is None or not isinstance(cursor_obj.get("id"), str):
            _log("error", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    runs = _load("agent_runs.json")
    # Filter
    out = []
    for r in runs:
        if r.get("workspace_id") != workspace_id:
            continue
        if session_id is not None and r.get("session_id") != session_id:
            continue
        if tool_id is not None and r.get("tool_id") != tool_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        r_ca = _parse_dt(r.get("created_at"))
        if ca and r_ca and not (r_ca > ca):
            continue
        if ca and r_ca is None:
            continue
        if cb and r_ca and not (r_ca < cb):
            continue
        if cb and r_ca is None:
            continue
        out.append(r)

    def _key_for(r):
        dt = _parse_dt(r.get("created_at"))
        dt_key = dt.isoformat() if dt else ""
        return (dt_key, r.get("id") or "")

    reverse = (sort == "created_at_desc")
    out.sort(key=_key_for, reverse=reverse)

    # Apply cursor after sort
    if cursor_obj is not None:
        c_dt = _parse_dt(cursor_obj.get("created_at"))
        c_id = cursor_obj.get("id")
        filtered = []
        for r in out:
            r_dt = _parse_dt(r.get("created_at"))
            r_id = r.get("id")
            if r_dt is None or r_id is None:
                continue
            if reverse:
                # created_at desc: next page are items strictly older (dt,id) < cursor
                if (r_dt, r_id) < (c_dt, c_id):
                    filtered.append(r)
            else:
                # asc: next page are items strictly newer (dt,id) > cursor
                if (r_dt, r_id) > (c_dt, c_id):
                    filtered.append(r)
        out = filtered

    total = len(out)
    page = out[:limit]
    has_more = total > limit

    # Prepare response runs
    resp_runs = []
    for r in page:
        rr = dict(r)
        if not include_input:
            rr.pop("input", None)
        else:
            if "input" in rr:
                rr["input"] = _redact_obj(rr.get("input"))
        resp_runs.append(rr)

    next_cursor = None
    if has_more and len(page) > 0:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        enc = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    # Update last_used_at
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for k in api_keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    _log("ok", workspace_id=workspace_id, api_key_id=key.get("id"), meta={"returned": len(resp_runs), "total": total, "has_more": has_more})
    return {
        "runs": resp_runs,
        "pagination": {"limit": limit, "has_more": has_more, "next_cursor": next_cursor, "total": total},
    }

def octagon_cancel_agent_run(workspace_id, run_id, reason=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0385000" if __import__("os").path.isdir("./environment_mix/0385000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "octagon-cancel-agent-run"
    t0 = time.time()

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                base = s[:-1]
                dt = datetime.datetime.fromisoformat(base)
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # --- request logging (observable dynamics) ---
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []

    def _log(status, ws_id=None, api_key_id=None, meta=None):
        now = _utcnow()
        row = {
            "id": f"oct_req_{int(time.time()*1000)}_{len(req_logs)+1}",
            "endpoint": endpoint,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        }
        if meta is not None:
            row["meta"] = meta
        req_logs.append(row)
        _save("request_logs.json", req_logs)

    # --- Validate inputs ---
    if not isinstance(workspace_id, str) or not re.match(r"^oct_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id must match ^oct_ws_[0-9A-HJKMNP-TV-Z]{10,}$.", field="workspace_id")
    if not isinstance(run_id, str) or not re.match(r"^oct_run_[0-9A-HJKMNP-TV-Z]{10,}$", run_id):
        _log("error", ws_id=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "run_id"})
        return _err("VALIDATION_ERROR", "run_id must match ^oct_run_[0-9A-HJKMNP-TV-Z]{10,}$.", field="run_id")
    if reason is not None and not isinstance(reason, str):
        _log("error", ws_id=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "reason"})
        return _err("VALIDATION_ERROR", "reason must be a string if provided.", field="reason")

    # --- Load data ---
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    runs = _load("agent_runs.json")

    if not isinstance(workspaces, list):
        workspaces = []
    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(runs, list):
        runs = []

    # --- Resolve workspace (do not leak deleted data) ---
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log("error", ws_id=workspace_id, meta={"code": "NOT_FOUND", "rule": "workspace_not_found"})
        return _err("NOT_FOUND", "Workspace not found.", rule="workspace_not_found")
    ws_status = ws.get("status")
    if ws_status == "deleted":
        _log("error", ws_id=workspace_id, meta={"code": "NOT_FOUND", "rule": "workspace_deleted"})
        return _err("NOT_FOUND", "Workspace not found.", rule="workspace_deleted")
    if ws_status != "active":
        _log("error", ws_id=workspace_id, meta={"code": "UNAUTHORIZED", "rule": "workspace_not_active", "workspace_status": ws_status})
        return _err("UNAUTHORIZED", "Workspace is not active; run cancellation is not permitted.", rule="workspace_not_active", workspace_status=ws_status)

    # --- Find run (must exist; do not report success without effect) ---
    run_idx = None
    run = None
    for i, r in enumerate(runs):
        if isinstance(r, dict) and r.get("id") == run_id:
            run_idx = i
            run = r
            break
    if run is None:
        _log("error", ws_id=workspace_id, meta={"code": "NOT_FOUND", "rule": "run_not_found"})
        return _err("NOT_FOUND", "Agent run not found.", rule="run_not_found")

    # --- Ownership checks (workspace/session consistency) ---
    # Real behavior: if caller provided a workspace_id that doesn't match the run, that's a conflict.
    run_ws_id = run.get("workspace_id")
    if run_ws_id != workspace_id:
        _log("error", ws_id=workspace_id, meta={"code": "CONFLICT", "rule": "run_workspace_mismatch", "run_workspace_id": run_ws_id})
        return _err(
            "CONFLICT",
            "Run does not belong to the provided workspace_id.",
            rule="run_workspace_mismatch",
            run_workspace_id=run_ws_id,
        )

    sess_id = run.get("session_id")
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sess_id), None)
    if sess is None:
        _log("error", ws_id=workspace_id, meta={"code": "NOT_FOUND", "rule": "session_not_found_for_run", "session_id": sess_id})
        return _err("NOT_FOUND", "Session for this run was not found.", rule="session_not_found_for_run", session_id=sess_id)
    if sess.get("workspace_id") != workspace_id:
        _log("error", ws_id=workspace_id, meta={"code": "CONFLICT", "rule": "run_session_workspace_mismatch", "session_workspace_id": sess.get("workspace_id")})
        return _err(
            "CONFLICT",
            "Run/session workspace mismatch.",
            rule="run_session_workspace_mismatch",
            session_workspace_id=sess.get("workspace_id"),
        )
    if sess.get("status") == "deleted":
        _log("error", ws_id=workspace_id, meta={"code": "NOT_FOUND", "rule": "session_deleted"})
        return _err("NOT_FOUND", "Session not found.", rule="session_deleted")

    # --- Ambient auth: only ensure there exists a valid key if run has api_key_id; otherwise allow (system/internal) ---
    api_key_id = run.get("api_key_id")
    if api_key_id is not None:
        key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
        if key is None or key.get("workspace_id") != workspace_id:
            _log("error", ws_id=workspace_id, api_key_id=api_key_id, meta={"code": "UNAUTHORIZED", "rule": "api_key_not_found_or_mismatch"})
            return _err("UNAUTHORIZED", "API key for this run is not valid for this workspace.", rule="api_key_not_found_or_mismatch")
        if key.get("status") != "active":
            _log("error", ws_id=workspace_id, api_key_id=api_key_id, meta={"code": "UNAUTHORIZED", "rule": "api_key_not_active", "api_key_status": key.get("status")})
            return _err("UNAUTHORIZED", "API key is not active.", rule="api_key_not_active", api_key_status=key.get("status"))
        exp = _parse_dt(key.get("expires_at"))
        if exp is not None and _utcnow() >= exp:
            _log("error", ws_id=workspace_id, api_key_id=api_key_id, meta={"code": "UNAUTHORIZED", "rule": "api_key_expired"})
            return _err("UNAUTHORIZED", "API key is expired.", rule="api_key_expired")

    # --- Lifecycle transition enforcement ---
    cur = run.get("status")
    allowed = {
        "queued": ["running", "cancelled", "failed"],
        "running": ["succeeded", "failed", "cancelled"],
        "succeeded": [],
        "failed": [],
        "cancelled": [],
    }
    if cur not in allowed:
        _log("error", ws_id=workspace_id, api_key_id=api_key_id, meta={"code": "VALIDATION_ERROR", "rule": "invalid_run_status", "status": cur})
        return _err("VALIDATION_ERROR", "Run has an invalid status.", rule="invalid_run_status", status=cur)

    if "cancelled" not in allowed.get(cur, []):
        _log("error", ws_id=workspace_id, api_key_id=api_key_id, meta={"code": "INVALID_TRANSITION", "from_status": cur, "to_status": "cancelled"})
        return _err(
            "INVALID_TRANSITION",
            f"Cannot cancel a run in status '{cur}'.",
            from_status=cur,
            to_status="cancelled",
            rule="run_cancel_not_allowed",
        )

    # --- Mutate run ---
    now = _utcnow()
    run_new = dict(run)
    run_new["status"] = "cancelled"
    run_new["finished_at"] = _iso(now)
    # Preserve started_at if present; compute duration only when possible.
    started = _parse_dt(run_new.get("started_at"))
    if started is not None:
        run_new["duration_ms"] = max(0, int((now - started).total_seconds() * 1000))
    elif run_new.get("duration_ms") is None:
        # leave as-is if present; else keep None
        run_new["duration_ms"] = None

    # Record reason in error fields for audit consistency; stable code.
    run_new["error_code"] = "user_cancelled"
    if isinstance(reason, str) and reason.strip():
        run_new["error_message"] = reason.strip()
    elif run_new.get("error_message") in (None, ""):
        run_new["error_message"] = "Cancelled by user."

    run_new["updated_at"] = _iso(now)

    runs[run_idx] = run_new
    _save("agent_runs.json", runs)

    # Touch api key last_used_at on successful authenticated action (if applicable)
    if api_key_id is not None:
        for i, k in enumerate(api_keys):
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k2 = dict(k)
                k2["last_used_at"] = _iso(now)
                k2["updated_at"] = _iso(now)
                api_keys[i] = k2
                _save("api_keys.json", api_keys)
                break

    _log("ok", ws_id=workspace_id, api_key_id=api_key_id, meta={"run_id": run_id})
    return {"run": run_new}
